from pathlib import Path
import json,sys
r=Path(__file__).parent;m=json.loads((r/'manifest.json').read_text());media=sys.argv[1] if len(sys.argv)>1 else 'Assigned by the immutable media publication; see publication receipt.'
publication=json.loads((r/'publication.json').read_text()) if (r/'publication.json').exists() else {}
